NAME = 'Wulfila: Bishop Wulfila Gothic Bible'
BOOK = 'Colossians'

CHAPTERS = {
    1: {
        6: '.... 𐌹𐌽 𐍃𐌿𐌽𐌾𐌰𐌹;',
        7: '𐍃𐍅𐌰𐍃𐍅𐌴 𐌲𐌰𐌽𐌴𐌼𐌿𐌸 𐌰𐍄 𐌰𐌹𐍀𐌰𐍆𐍂𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐌻𐌹𐌿𐌱𐌹𐌽 𐌲𐌰𐍃𐌺𐌰𐌻𐌺𐌾𐌰 𐌿𐌽𐍃𐌰𐍂𐌰𐌼𐌼𐌰, 𐍃𐌰𐌴𐌹 𐌹𐍃𐍄 𐍄𐍂𐌹𐌲𐌲𐍅𐍃 𐍆𐌰𐌿𐍂 𐌹𐌶𐍅𐌹𐍃 𐌰𐌽𐌳𐌱𐌰𐌷𐍄𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃 𐌹𐌴𐍃𐌿𐌹𐍃,',
        8: '𐍃𐌰𐌴𐌹 𐌾𐌰𐌷 𐌲𐌰𐌺𐌰𐌽𐌽𐌹𐌳𐌰 𐌿𐌽𐍃 𐌹𐌶𐍅𐌰𐍂𐌰 𐍆𐍂𐌹𐌰𐌸𐍅𐌰 𐌹𐌽 𐌰𐌷𐌼𐌹𐌽.',
        9: '𐌳𐌿𐌸𐌸𐌴 𐌾𐌰𐌷 𐍅𐌴𐌹𐍃, 𐍆𐍂𐌰𐌼 𐌸𐌰𐌼𐌼𐌰 𐌳𐌰𐌲𐌰 𐌴𐌹 𐌷𐌰𐌿𐍃𐌹𐌳𐌴𐌳𐌿𐌼, 𐌽𐌹 𐍈𐌴𐌹𐌻𐌰𐌹𐌳𐌴𐌳𐌿𐌼 𐍆𐌰𐌿𐍂 𐌹𐌶𐍅𐌹𐍃 𐌱𐌹𐌳𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌾𐌰𐌷 𐌰𐌹𐌷𐍄𐍂𐍉𐌽𐌳𐌰𐌽𐍃, 𐌴𐌹 𐍆𐌿𐌻𐌻𐌽𐌰𐌹𐌸 𐌺𐌿𐌽𐌸𐌾𐌹𐍃 𐍅𐌹𐌻𐌾𐌹𐌽𐍃 𐌹𐍃 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹 𐌷𐌰𐌽𐌳𐌿𐌲𐌴𐌹𐌽 𐌾𐌰𐌷 𐍆𐍂𐍉𐌳𐌴𐌹𐌽 𐌰𐌷𐌼𐌴𐌹𐌽𐌰𐌹;',
        10: '.... 𐍅𐌰𐌹𐍂𐌸𐌰𐌱𐌰 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌹𐌽 𐌰𐌻𐌻𐌰𐌼𐌼𐌰 𐌸𐌰𐍄𐌴𐌹 𐌲𐌰𐌻𐌴𐌹𐌺𐌰𐌹, 𐌹𐌽 𐌰𐌻𐌻𐌰𐌼𐌼𐌰 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌴 𐌲𐍉𐌳𐌰𐌹𐌶𐌴 𐌰𐌺𐍂𐌰𐌽 𐌱𐌰𐌹𐍂𐌰𐌽𐌳𐌰𐌽𐍃 𐌾𐌰𐌷 𐍅𐌰𐌷𐍃𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌽 𐌿𐍆𐌺𐌿𐌽𐌸𐌾𐌰 𐌲𐌿𐌳𐌹𐍃, 𐌴𐌹 𐌲𐌰𐌲𐌲𐌰𐌹𐌸 𐍅𐌰𐌹𐍂𐌸𐌰𐌱𐌰 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌹𐌽 𐌰𐌻𐌻𐌰𐌼𐌼𐌰 𐌸𐌰𐍄𐌴𐌹 𐌲𐌰𐌻𐌴𐌹𐌺𐌰𐌹, 𐌹𐌽 𐌰𐌻𐌻𐌰𐌼𐌼𐌰 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌴 𐌲𐍉𐌳𐌰𐌹𐌶𐌴 𐌰𐌺𐍂𐌰𐌽 𐌱𐌰𐌹𐍂𐌰𐌽𐌳𐌰𐌽𐍃 𐌾𐌰𐌷 𐍅𐌰𐌷𐍃𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌽 𐌿𐍆𐌺𐌿𐌽𐌸𐌾𐌰 𐌲𐌿(𐌳𐌹𐍃),',
        11: '𐌹𐌽 𐌰𐌻𐌻𐌰𐌹 𐌼𐌰𐌷𐍄𐌰𐌹 𐌲𐌰𐍃𐍅𐌹𐌽𐌸𐌹𐌳𐌰𐌹 𐌱𐌹 𐌼𐌰𐌷𐍄𐌰𐌹 𐍅𐌿𐌻𐌸𐌰𐌿𐍃 𐌹𐍃, 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹 𐌿𐍃𐌸𐌿𐌻𐌰𐌹𐌽𐌰𐌹 𐌾𐌰𐌷 𐌿𐍃𐌱𐌴𐌹𐍃𐌽𐌰𐌹 𐌼𐌹𐌸 𐍆𐌰𐌷𐌴𐌳𐌰𐌹, 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹 𐌼𐌰𐌷𐍄𐌰𐌹 𐌲𐌰𐍃𐍅𐌹𐌽𐌸𐌹𐌳𐌰𐌹 𐌱𐌹 𐌼𐌰𐌷𐍄𐌰𐌹 𐍅𐌿𐌻𐌸𐌰𐌿𐍃 𐌹𐍃, 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹 𐌿𐍃𐌸𐌿𐌻𐌰𐌹𐌽𐌰𐌹 𐌾𐌰𐌷 𐌿𐍃𐌱𐌴𐌹𐍃𐌽𐌰𐌹 𐌼𐌹𐌸 𐍆𐌰𐌷𐌴𐌳𐌰𐌹,',
        12: '𐌰𐍅𐌹𐌻𐌹𐌿𐌳𐍉𐌽𐌳𐌰𐌽𐍃 𐌰𐍄𐍄𐌹𐌽 𐍃𐌰𐌴𐌹 𐌻𐌰𐌸𐍉𐌳𐌰 𐌹𐌶𐍅𐌹𐍃 𐌳𐌿 𐌳𐌰𐌹𐌻𐌰𐌹 𐌷𐌻𐌰𐌿𐍄𐌹𐍃 𐍅𐌴𐌹𐌷𐌰𐌹𐌶𐌴 𐌹𐌽 𐌻𐌹𐌿𐌷𐌰𐌳𐌰[𐌹], 𐌰𐍅𐌹𐌻𐌹𐌿𐌳𐍉𐌽𐌳𐌰𐌽𐍃 𐌰𐍄𐍄𐌹𐌽 𐍃𐌰𐌴𐌹 𐌻𐌰𐌸𐍉𐌳𐌰 𐌹𐌶𐍅𐌹𐍃 𐌳𐌿 𐌳𐌰𐌹𐌻𐌰𐌹 𐌷𐌻𐌰𐌿𐍄𐌹𐍃 𐍅𐌴𐌹𐌷𐌰𐌹𐌶𐌴 𐌹𐌽 𐌻𐌹𐌿𐌷𐌰𐌳𐌰,',
        13: '𐍃𐌰𐌴𐌹 𐌲𐌰𐌻𐌰𐌿𐍃𐌹𐌳𐌰 𐌹𐌶𐍅𐌹𐍃 𐌿𐍃 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌾𐌰 𐍂𐌹𐌵𐌹𐌶𐌹𐍃 𐌾𐌰𐌷 𐌰𐍄𐌽𐌰𐌼 𐌹𐌽 𐌸𐌹𐌿𐌳𐌰𐌽𐌲𐌰𐍂𐌳𐌾𐌰 𐍃𐌿𐌽𐌿𐍃 𐍆𐍂𐌹𐌰𐌸𐍅𐍉𐍃 𐍃𐌴𐌹𐌽𐌰𐌹𐌶𐍉𐍃, 𐍃𐌰𐌴𐌹 𐌲𐌰𐌻𐌰𐌿𐍃𐌹𐌳𐌰 𐌹𐌶𐍅𐌹𐍃 𐌿𐍃 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌾𐌰 𐍂𐌹𐌵𐌹𐌶𐌹𐍃 𐌾𐌰𐌷 𐌰𐍄𐌽𐌰𐌼 𐌹𐌽 𐌸𐌹𐌿𐌳𐌰𐌽𐌲𐌰𐍂𐌳𐌾𐌰 𐍃𐌿𐌽𐌰𐌿𐍃 𐍆𐍂𐌹𐌰𐌸𐍅𐍉𐍃 𐍃𐌴𐌹𐌽𐌰𐌹𐌶𐍉𐍃,',
        14: '𐌹𐌽 𐌸𐌰𐌼𐌼𐌴𐌹 𐌷𐌰𐌱𐌰𐌼 𐍆𐌰𐌿𐍂𐌱𐌰𐌿𐌷𐍄, 𐍆𐍂𐌰𐌻𐌴𐍄 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌴, 𐌹𐌽 𐌸𐌰𐌼𐌼𐌴𐌹 𐌷𐌰𐌱𐌰𐌼 𐍆𐌰𐌿𐍂𐌱𐌰𐌿𐌷𐍄, 𐍆𐍂𐌰𐌻𐌴𐍄 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌴,',
        15: '𐍃𐌰𐌴𐌹 𐌹𐍃𐍄 𐍆𐍂𐌹𐍃𐌰𐌷𐍄𐍃 𐌲𐌿𐌳𐌹𐍃 𐌿𐌽𐌲𐌰𐍃𐌰𐌹𐍈𐌰𐌽𐌹𐍃, 𐍆𐍂𐌿𐌼𐌰𐌱𐌰𐌿𐍂 𐌰𐌻𐌻𐌰𐌹𐌶𐍉𐍃 𐌲𐌰𐍃𐌺𐌰𐍆𐍄𐌰𐌹𐍃; 𐍃𐌰𐌴𐌹 𐌹𐍃𐍄 𐍆𐍂𐌹𐍃𐌰𐌷𐍄𐍃 𐌲𐌿𐌳𐌹𐍃 𐌿𐌽𐌲𐌰𐍃𐌰𐌹𐍈𐌰𐌽𐌹𐍃, 𐍆𐍂𐌿𐌼𐌰𐌱𐌰𐌿𐍂 𐌰𐌻𐌻𐌰𐌹𐌶𐍉𐍃 𐌲𐌰𐍃𐌺𐌰𐍆𐍄𐌰𐌹𐍃;',
        16: '𐌿𐌽𐍄𐌴 𐌹𐌽 𐌹𐌼𐌼𐌰 𐌲𐌰𐍃𐌺𐌰𐍀𐌰𐌽𐌰 𐍅𐌰𐌿𐍂𐌸𐌿𐌽 𐌰𐌻𐌻𐌰 𐌹𐌽 𐌷𐌹𐌼𐌹𐌽𐌰𐌼 𐌾𐌰𐌷 𐌰𐌽𐌰 𐌰𐌹𐍂𐌸𐌰𐌹, 𐌸𐍉 𐌲𐌰𐍃𐌰𐌹𐍈𐌰𐌽𐍉𐌽𐌰 𐌾𐌰𐌸~𐌸𐍉 𐌿𐌽𐌲𐌰𐍃𐌰𐌹𐍈𐌰𐌽𐍉𐌽𐌰, 𐌾𐌰𐌸𐌸𐌴 𐍃𐌹𐍄𐌻𐍉𐍃 𐌾𐌰𐌸𐌸𐌴 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐌰𐍃𐍃𐌾𐌿𐍃, 𐌾𐌰𐌸𐌸𐌴 𐍂𐌴𐌹𐌺𐌾𐌰 𐌾𐌰𐌸𐌸𐌴 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌾𐌰, 𐌰𐌻𐌻𐌰 𐌸𐌰𐌹𐍂𐌷 𐌹𐌽𐌰 𐌾𐌰𐌷 𐌹𐌽 𐌹𐌼𐌼𐌰 𐌲𐌰𐍃𐌺𐌰𐍀𐌰𐌽𐌰 𐍃𐌹𐌽𐌳. 𐌿𐌽𐍄𐌴 𐌹𐌽 𐌹𐌼𐌼𐌰 𐌲𐌰𐍃𐌺𐌰𐍀𐌰𐌽𐌰 𐍅𐌰𐌿𐍂𐌸𐌿𐌽 𐌰𐌻𐌻𐌰 𐌹𐌽 𐌷𐌹𐌼𐌹𐌽𐌰𐌼 𐌾𐌰𐌷 𐌰𐌽𐌰 𐌰𐌹𐍂𐌸𐌰𐌹, 𐌸𐍉 𐌲𐌰𐍃𐌰𐌹𐍈𐌰𐌽𐍉𐌽𐌰 𐌾𐌰𐌷 𐌸𐍉 𐌿𐌽𐌲𐌰𐍃𐌰𐌹𐍈𐌰𐌽𐍉𐌽𐌰, 𐌾𐌰𐌸𐌸𐌴 𐍃𐌹𐍄𐌻𐍉𐍃 𐌾𐌰𐌸𐌸𐌴 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐌰𐍃𐍃𐌾𐌿𐍃, 𐌾𐌰𐌸𐌸𐌴 𐍂𐌴𐌹𐌺𐌾𐌰 𐌾𐌰𐌸𐌸𐌴 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌾𐌰, 𐌰𐌻𐌻𐌰 𐌸𐌰𐌹𐍂𐌷 𐌹𐌽𐌰 𐌾𐌰𐌷 𐌹𐌽 𐌹𐌼𐌼𐌰 𐌲𐌰𐍃𐌺𐌰𐍀𐌰𐌽𐌰 𐍃𐌹𐌽𐌳.',
        17: '𐌾𐌰𐌷 𐌹𐍃 𐌹𐍃𐍄 𐍆𐌰𐌿𐍂𐌰 𐌰𐌻𐌻𐌰𐌹𐌼 𐌾𐌰𐌷 𐌰𐌻𐌻𐌰 𐌹𐌽 𐌹𐌼𐌼𐌰 𐌿𐍃𐍃𐌰𐍄𐌹𐌳𐌰 𐍃𐌹𐌽𐌳. 𐌾𐌰𐌷 𐌹𐍃 𐌹𐍃𐍄 𐍆𐌰𐌿𐍂𐌰 𐌰𐌻𐌻𐌰𐌹𐌼 𐌾𐌰𐌷 𐌰𐌻𐌻𐌰 𐌹𐌽 𐌹𐌼𐌼𐌰 𐌿𐍃𐍃𐌰𐍄𐌹𐌳𐌰 𐍃𐌹𐌽𐌳.',
        18: '𐌾𐌰𐌷 𐌹𐍃 𐌹𐍃𐍄 𐌷𐌰𐌿𐌱𐌹𐌸 𐌻𐌴𐌹𐌺𐌹𐍃, 𐌰𐌹𐌺𐌺𐌻𐌴𐍃𐌾𐍉𐌽𐍃, 𐍃𐌰𐌴𐌹 𐌹𐍃𐍄 𐌰𐌽𐌰𐍃𐍄𐍉𐌳𐌴𐌹𐌽𐍃, 𐍆𐍂𐌿𐌼𐌰𐌱𐌰𐌿𐍂 𐌿𐍃 𐌳𐌰𐌿𐌸𐌰𐌹𐌼, 𐌴𐌹 𐍃𐌹𐌾𐌰𐌹 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹𐌼 𐌹𐍃 𐍆𐍂𐌿𐌼𐌰𐌳𐌴𐌹𐌽 𐌷𐌰𐌱𐌰𐌽𐌳𐍃; 𐌾𐌰𐌷 𐌹𐍃 𐌹𐍃𐍄 𐌷𐌰𐌿𐌱𐌹𐌸 𐌻𐌴𐌹𐌺𐌹𐍃, 𐌰𐌹𐌺𐌺𐌻𐌴𐍃𐌾𐍉𐌽𐍃, 𐍃𐌰𐌴𐌹 𐌹𐍃𐍄 𐌰𐌽𐌰𐍃𐍄𐍉𐌳𐌴𐌹𐌽𐍃, 𐍆𐍂𐌿𐌼𐌰𐌱𐌰𐌿𐍂 𐌿𐍃 𐌳𐌰𐌿𐌸𐌰𐌹𐌼, 𐌴𐌹 𐍃𐌹𐌾𐌰𐌹 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹𐌼 𐌹𐍃 𐍆𐍂𐌿𐌼𐌰𐌳𐌴𐌹𐌽 𐌷𐌰𐌱𐌰𐌽𐌳𐍃;',
        19: '𐌿𐌽𐍄𐌴 𐌹𐌽 𐌹𐌼𐌼𐌰 𐌲𐌰𐌻𐌴𐌹𐌺𐌰𐌹𐌳𐌰 𐌰𐌻𐌻𐌰 𐍆𐌿𐌻𐌻𐍉𐌽 𐌱𐌰𐌿𐌰𐌽, 𐌿𐌽𐍄𐌴 𐌹𐌽 𐌹𐌼𐌼𐌰 𐌲𐌰𐌻𐌴𐌹𐌺𐌰𐌹𐌳𐌰 𐌰𐌻𐌻𐌰 𐍆𐌿𐌻𐌻𐍉𐌽 𐌱𐌰𐌿𐌰𐌽,',
        20: '𐌾𐌰𐌷 𐌸𐌰𐌹𐍂𐌷 𐌹𐌽𐌰 𐌲𐌰𐍆𐍂𐌹𐌸𐍉𐌽 𐌰𐌻𐌻𐌰 𐌹𐌽 𐌹𐌼𐌼𐌰, 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹 𐍄𐌰𐌿𐌾𐌰𐌽𐌳𐍃 𐌸𐌰𐌹𐍂𐌷 𐌱𐌻𐍉𐌸 𐌲𐌰𐌻𐌲𐌹𐌽𐍃 𐌹𐍃 𐌸𐌰𐌹𐍂𐌷 𐌹𐌽𐌰, 𐌾𐌰𐌸𐌸𐌴 𐌸𐍉 𐌰𐌽𐌰 𐌰𐌹𐍂𐌸𐌰𐌹 𐌾𐌰𐌸𐌸𐌴 𐌸𐍉 𐌰𐌽𐌰 𐌷𐌹𐌼𐌹𐌽𐌰𐌼. 𐌾𐌰𐌷 𐌸𐌰𐌹𐍂𐌷 𐌹𐌽𐌰 𐌲𐌰𐍆𐍂𐌹𐌸𐍉𐌽 𐌰𐌻𐌻𐌰 𐌹𐌽 𐌹𐌼𐌼𐌰, 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹 𐍄𐌰𐌿𐌾𐌰𐌽𐌳𐍃 𐌸𐌰𐌹𐍂𐌷 𐌱𐌻𐍉𐌸 𐌲𐌰𐌻𐌲𐌹𐌽𐍃 𐌹𐍃 𐌸𐌰𐌹𐍂𐌷 𐌹𐌽𐌰, 𐌾𐌰𐌸𐌸𐌴 𐌸𐍉 𐌰𐌽𐌰 𐌰𐌹𐍂𐌸𐌰𐌹 𐌾𐌰𐌸𐌸𐌴 𐌸𐍉 𐌰𐌽𐌰 𐌷𐌹𐌼𐌹𐌽𐌰𐌼.',
        21: '𐌾𐌰𐌷 𐌹(𐌶𐍅𐌹𐍃) 𐍃𐌹𐌼𐌻𐌴 𐍅𐌹𐍃𐌰𐌽𐌳𐌰𐌽𐍃 𐍆𐍂𐌰𐌼𐌰𐌸𐌹𐌳𐌰𐌽𐍃 𐌾𐌰𐌷 𐍆𐌹𐌾𐌰𐌽𐌳𐍃 𐌲𐌰𐌷𐌿𐌲𐌳𐌰𐌹 𐌹𐌽 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰𐌼 𐌿𐌱𐌹𐌻𐌰𐌹𐌼, 𐌹𐌸 𐌽𐌿 𐌲𐌰𐍆𐍂𐌹𐌸𐍉𐌳𐌰𐌹 𐌾𐌰𐌷 𐌹𐌶𐍅𐌹𐍃 𐍃𐌹𐌼𐌻𐌴 𐍅𐌹𐍃𐌰𐌽𐌳𐌰𐌽𐍃 𐍆𐍂𐌰𐌼𐌰𐌸𐌹𐌳𐌰𐌽𐍃 𐌾𐌰𐌷 𐍆𐌹𐌾𐌰𐌽𐌳𐍃 𐌲𐌰𐌷𐌿𐌲𐌳𐌰𐌹 𐌹𐌽 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰𐌼 𐌿𐌱𐌹𐌻𐌰𐌹𐌼, 𐌹𐌸 𐌽𐌿 𐌲𐌰𐍆𐍂𐌹𐌸𐍉𐌳𐌰𐌹',
        22: '𐌹𐌽 𐌻𐌴𐌹𐌺𐌰 𐌼𐌰𐌼𐌼𐍉𐌽𐍃 𐌹𐍃 𐌸𐌰𐌹𐍂𐌷 𐌳𐌰𐌿𐌸𐌿 𐌳𐌿 𐌰𐍄𐍃𐌰𐍄𐌾𐌰𐌽 𐌹𐌶𐍅𐌹𐍃 𐍅𐌴𐌹𐌷𐌰𐌽𐍃 𐌾𐌰𐌷 𐌿𐌽𐍅𐌰𐌼𐌼𐌰𐌽𐍃 𐌾𐌰𐌷 𐌿𐍃𐍆𐌰𐌹𐍂𐌹𐌽𐌰𐌽𐍃 𐍆𐌰𐌿𐍂𐌰 𐌹𐌼𐌼𐌰, 𐌹𐌽 𐌻𐌴𐌹𐌺𐌰 𐌼𐌰𐌼𐌼𐍉𐌽𐍃 𐌹𐍃 𐌸𐌰𐌹𐍂𐌷 𐌳𐌰𐌿𐌸𐌿 𐌳𐌿 𐌰𐍄𐍃𐌰𐍄𐌾𐌰𐌽 𐌹𐌶𐍅𐌹𐍃 𐍅𐌴𐌹𐌷𐌰𐌽𐍃 𐌾𐌰𐌷 𐌿𐌽𐍅𐌰𐌼𐌼𐌰𐌽𐍃 𐌾𐌰𐌷 𐌿𐍃𐍆𐌰𐌹𐍂𐌹𐌽𐌰𐌽𐍃 𐍆𐌰𐌿𐍂𐌰 𐌹𐌼𐌼𐌰,',
        23: '𐌾𐌰𐌱𐌰𐌹 𐍃𐍅𐌴𐌸𐌰𐌿𐌷 𐌸𐌰𐌹𐍂𐌷𐍅𐌹𐍃𐌹𐌸 𐌹𐌽 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹 𐌲𐌰𐌸𐍅𐌰𐍃𐍄𐌹𐌳𐌰𐌹 𐌾𐌰𐌷 𐌲𐌰𐍄𐌿𐌻𐌲𐌹𐌳𐌰𐌹 𐌾𐌰𐌷 𐌽𐌹 𐌰𐍆𐍅𐌰𐌲𐌹𐌳𐌰𐌹 𐌰𐍆 𐍅𐌴𐌽𐌰𐌹 𐌰𐌹𐍅𐌰𐌲𐌲𐌴𐌻𐌾𐍉𐌽𐍃, 𐌸𐍉𐌴𐌹 𐌷𐌰𐌿𐍃𐌹𐌳𐌴𐌳𐌿𐌸, 𐍃𐌴𐌹 𐌼𐌴𐍂𐌹𐌳𐌰 𐌹𐍃𐍄 𐌹𐌽 𐌰𐌻𐌻𐌰 𐌲𐌰𐍃𐌺𐌰𐍆𐍄 𐌸𐍉 𐌿𐍆 𐌷𐌹𐌼𐌹𐌽𐌰, 𐌸𐌹𐌶𐍉𐌶𐌴𐌹 𐍅𐌰𐍂𐌸 𐌹𐌺 𐍀𐌰𐍅𐌻𐌿𐍃 𐌰𐌽𐌳𐌱𐌰𐌷𐍄𐍃; 𐌾𐌰𐌱𐌰𐌹 𐍃𐍅𐌴𐌸𐌰𐌿𐌷 𐌸𐌰𐌹𐍂𐌷𐍅𐌹𐍃𐌹𐌸 𐌹𐌽 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹 𐌲𐌰𐌸𐍅𐌰𐍃𐍄𐌹𐌳𐌰𐌹 𐌾𐌰𐌷 𐌲𐌰𐍄𐌿𐌻𐌲𐌹𐌳𐌰𐌹 𐌾𐌰𐌷 𐌽𐌹 𐌰𐍆𐍅𐌰𐌲𐌹𐌳𐌰𐌹 𐌰𐍆 𐍅𐌴𐌽𐌰𐌹 𐌰𐌹𐍅𐌰𐌲𐌲𐌴𐌻𐌾𐍉𐌽𐍃, 𐌸𐍉𐌴𐌹 𐌷𐌰𐌿𐍃𐌹𐌳𐌴𐌳𐌿𐌸, 𐍃𐌴𐌹 𐌼𐌴𐍂𐌹𐌳𐌰 𐌹𐍃𐍄 𐌹𐌽 𐌰𐌻𐌻𐌰 𐌲𐌰𐍃𐌺𐌰𐍆𐍄 𐌸𐍉 𐌿𐍆 𐌷𐌹𐌼𐌹𐌽𐌰, 𐌸𐌹𐌶𐍉𐌶𐌴𐌹 𐍅𐌰𐍂𐌸 𐌹𐌺 𐍀𐌰𐍅𐌻𐌿𐍃 𐌰𐌽𐌳𐌱𐌰𐌷𐍄𐍃;',
        24: '[𐍃𐌰𐌴𐌹] 𐌽𐌿 𐍆𐌰𐌲𐌹𐌽𐍉 𐌹𐌽 𐌸𐌰𐌹𐌼𐌴𐌹 𐍅𐌹𐌽𐌽𐌰 𐍆𐌰𐌿𐍂 𐌹𐌶𐍅𐌹𐍃 𐌾𐌰𐌷 𐌿𐍃𐍆𐌿𐌻𐌻𐌾𐌰 𐌲𐌰𐌹𐌳𐍅𐌰 𐌰𐌲𐌻𐍉𐌽𐍉 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃 𐌹𐌽 𐌻𐌴𐌹𐌺𐌰 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰 𐍆𐌰𐌿𐍂 𐌻𐌴𐌹𐌺 𐌹𐍃, 𐌸𐌰𐍄𐌴𐌹 𐌹𐍃𐍄 𐌰𐌹𐌺𐌺𐌻𐌴𐍃𐌾𐍉, [𐍃𐌰𐌴𐌹] 𐌽𐌿 𐍆𐌰𐌲𐌹𐌽𐍉 𐌹𐌽 𐌸𐌰𐌹𐌼𐌴𐌹 𐍅𐌹𐌽𐌽𐌰 𐍆𐌰𐌿𐍂 𐌹𐌶𐍅𐌹𐍃 𐌾𐌰𐌷 𐌿𐍃𐍆𐌿𐌻𐌻𐌾𐌰 𐌲𐌰𐌹𐍅𐌰 𐌰𐌲𐌻𐍉𐌽𐍉 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃 𐌹𐌽 𐌻𐌴𐌹𐌺𐌰 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰 𐍆𐌰𐌿𐍂 𐌻𐌴𐌹𐌺 𐌹𐍃, 𐌸𐌰𐍄𐌴𐌹 𐌹𐍃𐍄 𐌰𐌹𐌺𐌺𐌻𐌴𐍃𐌾𐍉,',
        25: '𐌸𐌹𐌶𐍉𐌶𐌴𐌹 𐍅𐌰𐍂𐌸 𐌹𐌺 𐌰𐌽𐌳𐌱𐌰𐌷𐍄𐍃 𐌱𐌹 𐍂𐌰𐌲𐌹𐌽𐌰 𐌲𐌿𐌳𐌹𐍃, 𐌸𐌰𐍄𐌴𐌹 𐌲𐌹𐌱𐌰𐌽 𐌹𐍃𐍄 𐌼𐌹𐍃 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃 𐌳𐌿 𐌿𐍃𐍆𐌿𐌻𐌻𐌾𐌰𐌽 𐍅𐌰𐌿𐍂𐌳 𐌲𐌿𐌳𐌹𐍃, 𐌸𐌹𐌶𐍉𐌶𐌴𐌹 𐍅𐌰𐍂𐌸 𐌹𐌺 𐌰𐌽𐌳𐌱𐌰𐌷𐍄𐍃 𐌱𐌹 𐍂𐌰𐌲𐌹𐌽𐌰 𐌲𐌿𐌳𐌹𐍃, 𐌸𐌰𐍄𐌴𐌹 𐌲𐌹𐌱𐌰𐌽 𐌹𐍃𐍄 𐌼𐌹𐍃 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃 𐌳𐌿 𐌿𐍃𐍆𐌿𐌻𐌻𐌾𐌰𐌽 𐍅𐌰𐌿𐍂𐌳 𐌲𐌿𐌳𐌹𐍃,',
        26: '𐍂𐌿𐌽𐌰 𐍃𐌴𐌹 𐌲𐌰𐍆𐌿𐌻𐌲𐌹𐌽𐌰 𐍅𐌰𐍃 𐍆𐍂𐌰𐌼 𐌰𐌹𐍅𐌰𐌼 𐌾𐌰𐌷 𐍆𐍂𐌰𐌼 𐌰𐌻𐌳𐌹𐌼, 𐌹𐌸 𐌽𐌿 𐌲𐌰𐍃𐍅𐌹𐌺𐌿𐌽𐌸𐌹𐌳𐌰 𐍅𐌰𐍂𐌸 𐌸𐌰𐌹𐌼 𐍅𐌴𐌹𐌷𐌰𐌼 𐌹𐍃, 𐍂𐌿𐌽𐌰 𐍃𐌴𐌹 𐌲𐌰𐍆𐌿𐌻𐌲𐌹𐌽𐌰 𐍅𐌰𐍃 𐍆𐍂𐌰𐌼 𐌰𐌹𐍅𐌰𐌼 𐌾𐌰𐌷 𐍆𐍂𐌰𐌼 𐌰𐌻𐌳𐌹𐌼, 𐌹𐌸 𐌽𐌿 𐌲𐌰𐍃𐍅𐌹𐌺𐌿𐌽𐌸𐌹𐌳𐌰 𐍅𐌰𐍂𐌸 𐌸𐌰𐌹𐌼 𐍅𐌴𐌹𐌷𐌰𐌼 𐌹𐍃,',
        27: '𐌸𐌰𐌹𐌼𐌴𐌹 𐍅𐌹𐌻𐌳𐌰 𐌲𐌿𐌸 𐌲𐌰𐌺𐌰𐌽𐌽𐌾𐌰𐌽 𐌲𐌰𐌱𐌴𐌹𐌽 𐍅𐌿𐌻𐌸𐌰𐌿𐍃 𐌸𐌹𐌶𐍉𐍃 𐍂𐌿𐌽𐍉𐍃 𐌹𐌽 𐌸𐌹𐌿𐌳𐍉𐌼, 𐌸𐌰𐍄𐌴𐌹 𐌹𐍃𐍄 𐍇𐍂𐌹𐍃𐍄𐌿𐍃 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃, 𐍅𐌴𐌽𐍃 𐍅𐌿𐌻𐌸𐌰𐌿𐍃, 𐌸𐌰𐌹𐌼𐌴𐌹 𐍅𐌹𐌻𐌳𐌰 𐌲𐌿𐌸 𐌲𐌰𐌺𐌰𐌽𐌽𐌾𐌰𐌽 𐌲𐌰𐌱𐌴𐌹𐌽 𐍅𐌿𐌻𐌸𐌰𐌿𐍃 𐌸𐌹𐌶𐍉𐍃 𐍂𐌿𐌽𐍉𐍃 𐌹𐌽 𐌸𐌹𐌿𐌳𐍉𐌼, 𐌸𐌰𐍄𐌴𐌹 𐌹𐍃𐍄 𐍇𐍂𐌹𐍃𐍄𐌿𐍃 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃, 𐍅𐌴𐌽𐍃 𐍅𐌿𐌻𐌸𐌰𐌿𐍃,',
        28: '𐌸𐌰𐌽𐌴𐌹 𐍅𐌴𐌹𐍃 𐌲𐌰𐍄𐌴𐌹𐌷𐌰𐌼 𐍄𐌰𐌻𐌶𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌰𐌻𐌻 𐌼𐌰𐌽𐌽𐌴 𐌾𐌰𐌷 𐌻𐌰𐌹𐍃𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌰𐌻𐌻 𐌼𐌰𐌽𐌽𐌴 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹 𐌷𐌰𐌽𐌳𐌿𐌲𐌴𐌹𐌽, 𐌴𐌹 𐌰𐍄𐍃𐌰𐍄𐌾𐌰𐌹𐌼𐌰 𐌰𐌻𐌻 𐌼𐌰𐌽𐌽𐌴 𐍆𐌿𐌻𐌻𐌰𐍅𐌹𐍄𐌰𐌽 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿, 𐌸𐌰𐌽𐌴𐌹 𐍅𐌴𐌹𐍃 𐌲𐌰𐍄𐌴𐌹𐌷𐌰𐌼 𐍄𐌰𐌻𐌶𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌰𐌻𐌻 𐌼𐌰𐌽𐌽𐌴 𐌾𐌰𐌷 𐌻𐌰𐌹𐍃𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌰𐌻𐌻 𐌼𐌰𐌽𐌽𐌴 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹 𐌷𐌰𐌽𐌳𐌿𐌲𐌴𐌹𐌽, 𐌴𐌹 𐌰𐍄𐍃𐌰𐍄𐌾𐌰𐌹𐌼𐌰 𐌰𐌻𐌻 𐌼𐌰𐌽𐌽𐌴 𐍆𐌿𐌻𐌻𐌰𐍅𐌹𐍄𐌰𐌽 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿,',
        29: '𐌳𐌿 𐌸𐌰𐌼𐌼𐌴𐌹 𐌰𐍂𐌱𐌰𐌹𐌳𐌾𐌰 𐌿𐍃𐌳𐌰𐌿𐌳𐌾𐌰𐌽𐌳𐍃 𐌱𐌹 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰 𐍃𐌴𐌹 𐌹𐌽𐌽𐌰 𐌿𐍃𐍅𐌰𐌿𐍂𐌺𐌴𐌹𐌸 𐌹𐌽 𐌼𐌹𐍃 𐌹𐌽 𐌼𐌰𐌷𐍄𐌰𐌹.... 𐌳𐌿 𐌸𐌰𐌼𐌼𐌴𐌹 𐌰𐍂𐌱𐌰𐌹𐌳𐌾𐌰 𐌿𐍃𐌳𐌰𐌿𐌳𐌾𐌰𐌽𐌳𐍃 𐌱𐌹....',
    },
    2: {
        11: '.... 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌴 𐌻𐌴𐌹𐌺𐌹𐍃, 𐌹𐌽 𐌱𐌹𐌼𐌰𐌹𐍄𐌰 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃,',
        12: '𐌼𐌹𐌸 𐌲𐌰𐌽𐌰𐍅𐌹𐍃𐍄𐍂𐍉𐌳𐌰𐌹 𐌹𐌼𐌼𐌰 𐌹𐌽 𐌳𐌰𐌿𐍀𐌴𐌹𐌽𐌰𐌹, 𐌹𐌽 𐌸𐌹𐌶𐌰𐌹𐌴𐌹 𐌾𐌰𐌷 𐌼𐌹𐌸𐌿𐍂𐍂𐌹𐍃𐌿𐌸 𐌸𐌰𐌹𐍂𐌷 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌹𐍃 𐌲𐌿𐌳𐌹𐍃, 𐍃𐌰𐌴𐌹 𐌿𐍂𐍂𐌰𐌹𐍃𐌹𐌳𐌰 𐌹𐌽(𐌰) 𐌿𐍃 𐌳𐌰𐌿𐌸𐌰𐌹𐌼.',
        13: '𐌾𐌰𐌷 𐌹𐌶𐍅𐌹𐍃 𐌳𐌰𐌿𐌸𐌰𐌽𐍃 𐍅𐌹𐍃𐌰𐌽𐌳𐌰𐌽𐍃 𐌼𐌹𐍃𐍃𐌰𐌳𐌴𐌳𐌹𐌼 𐌾𐌰𐌷 𐌿𐌽𐌱𐌹𐌼𐌰𐌹𐍄𐌰 𐌻𐌴𐌹𐌺𐌹𐍃 𐌹𐌶𐍅𐌰𐍂𐌹𐍃 𐌼𐌹𐌸𐌲𐌰𐌵𐌹𐍅𐌹𐌳𐌰 𐌼𐌹𐌸 𐌹𐌼𐌼𐌰, 𐍆𐍂𐌰𐌲𐌹𐌱𐌰𐌽𐌳𐍃 𐌿𐌽𐍃 𐌰𐌻𐌻𐍉𐍃 𐌼𐌹𐍃𐍃𐌰𐌳𐌴𐌳𐌹𐌽𐍃,',
        14: '𐌰𐍆𐍃𐍅𐌰𐌹𐍂𐌱𐌰𐌽𐌳𐍃 𐌸𐍉𐍃 𐌰𐌽𐌰 𐌿𐌽𐍃 𐍅𐌰𐌳𐌾𐌰𐌱𐍉𐌺𐍉𐍃 𐍂𐌰𐌲𐌹𐌽𐌰𐌼 𐍃𐌴𐌹𐌽𐌰𐌹𐌼, 𐌸𐌰𐍄𐌴𐌹 𐍅𐌰𐍃 𐌰𐌽𐌳𐌰𐌽𐌴𐌹𐌸𐍉 𐌿𐌽𐍃, 𐌾𐌰𐌷 𐌸𐌰𐍄𐌰 𐌿𐍃𐌽𐌰𐌼 𐌿𐍃 𐌼𐌹𐌳𐌿𐌼𐌰𐌹 𐌲𐌰𐌽𐌰𐌲𐌻𐌾𐌰𐌽𐌳𐍃 𐌹𐍄𐌰 𐌳𐌿 𐌲𐌰𐌻𐌲𐌹𐌽,',
        15: '𐌰𐌽𐌳𐌷𐌰𐌼𐍉𐌽𐌳𐍃 𐍃𐌹𐌺 𐌻𐌴𐌹𐌺𐌰, 𐍂𐌴𐌹𐌺𐌾𐌰 𐌾𐌰𐌷 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌾𐌰 𐌲𐌰𐍄𐌰𐍂𐌷𐌹𐌳𐌰 𐌱𐌰𐌻𐌸𐌰𐌱𐌰, 𐌲𐌰𐌱𐌻𐌰𐌿𐌸𐌾𐌰𐌽𐌳𐍃 𐌸𐍉 𐌱𐌰𐌹𐍂𐌷𐍄𐌰𐌱𐌰 𐌹𐌽 𐍃𐌹𐍃.',
        16: '𐌽𐌹 𐌼𐌰𐌽𐌽𐌰 𐌽𐌿 𐌹𐌶𐍅𐌹𐍃 𐌱𐌹𐌳𐍉𐌼𐌾𐌰𐌹 𐌹𐌽 𐌼𐌰𐍄𐌰 𐌰𐌹𐌸𐌸𐌰𐌿 𐌹𐌽 𐌳𐍂𐌰𐌲𐌲𐌺𐌰 𐌰𐌹𐌸𐌸𐌰𐌿 𐌹𐌽 𐌳𐌰𐌹𐌻𐌰𐌹 𐌳𐌰𐌲𐌹𐍃 𐌳𐌿𐌻𐌸𐌰𐌹𐍃 𐌰𐌹𐌸𐌸𐌰𐌿 𐍆𐌿𐌻𐌻𐌹𐌸𐌴 𐌰𐌹𐌸𐌸𐌰𐌿 𐍃𐌰𐌱𐌱𐌰𐍄𐌿𐌼,',
        17: '𐌸𐌰𐍄𐌴𐌹 𐌹𐍃𐍄 𐍃𐌺𐌰𐌳𐌿𐍃 𐌸𐌹𐌶𐌴 𐌰𐌽𐌰𐍅𐌰𐌹𐍂𐌸𐌰𐌽𐌴, 𐌹𐌸 𐌻𐌴𐌹𐌺 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃.',
        18: '𐌽𐌹 𐍈𐌰𐍃𐌷𐌿𐌽 𐌹𐌶𐍅𐌹𐍃 𐌲𐌰𐌾𐌹𐌿𐌺𐌰𐌹, 𐍅𐌹𐌻𐌾𐌰𐌽𐌳𐍃 𐌹𐌽 𐌷𐌰𐌿𐌽𐌴𐌹𐌽𐌰𐌹 𐌾𐌰𐌷 𐌱𐌻𐍉𐍄𐌹𐌽𐌰𐍃𐍃𐌰𐌿 𐌰𐌲𐌲𐌹𐌻𐌴 𐌸𐌰𐍄𐌴𐌹 𐌽𐌹 𐍃𐌰𐍈 𐌿𐍃𐌷𐌰𐍆𐌾𐌰𐌽𐌳𐍃 𐍃𐌹𐌺, 𐍃𐍅𐌰𐍂𐌴 𐌿𐍆𐌱𐌻𐌴𐍃𐌰𐌽𐍃 𐍆𐍂𐌰𐌼 𐍆𐍂𐌰𐌸𐌾𐌰 𐌻𐌴𐌹𐌺𐌹𐍃 𐍃𐌴𐌹𐌽𐌹𐍃,',
        19: '𐌾𐌰𐌷 𐌽𐌹 𐌷𐌰𐌱𐌰𐌽𐌳𐍃 𐌷𐌰𐌿𐌱𐌹𐌸, 𐌿𐍃 𐌸𐌰𐌼𐌼𐌴𐌹 𐌰𐌻𐌻 𐌻𐌴𐌹𐌺 𐌸𐌰𐌹𐍂𐌷 𐌲𐌰𐍅𐌹𐍃𐍃𐌹𐌽𐍃 𐌾𐌰𐌷 𐌲𐌰𐌱𐌹𐌽𐌳𐍉𐍃 𐌰𐌿𐌺𐌽𐌰𐌽𐌳𐍉 𐌾𐌰𐌷 𐌸𐌴𐌹𐌷𐌰𐌽𐌳𐍉 𐍅𐌰𐌷𐍃𐌴𐌹𐌸 𐌳𐌿 𐍅𐌰𐌷𐍃𐍄𐌰𐌿 𐌲𐌿𐌳𐌹𐍃.',
        20: '.... 𐌸𐌹𐍃 𐍆𐌰𐌹𐍂𐍈𐌰𐌿𐍃, 𐍈𐌰[𐌽] 𐌸𐌰𐌽𐌰𐍃𐌴𐌹𐌸𐍃 𐍃𐍅𐌴 𐌵𐌹𐍅𐌰𐌹 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿 𐌿𐍂𐍂𐌴𐌳𐌹𐌸? 𐌾𐌰𐌱𐌰𐌹 𐌲𐌰𐍃𐍅𐌿𐌻𐍄𐌿𐌸 𐌼𐌹𐌸 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌰𐍆 𐍃𐍄𐌰𐌱𐌹𐌼 𐌸𐌹𐍃 𐍆𐌰𐌹𐍂𐍈𐌰𐌿𐍃, 𐍈𐌰 𐌸𐌰𐌽𐌰𐍃𐌴𐌹𐌸𐍃 𐍃𐍅𐌴 𐌵𐌹𐍅𐌰𐌹 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿 𐌿𐍂𐍂𐌴𐌳𐌹𐌸?',
        21: '𐌽𐌹 𐍄𐌴𐌹𐌺𐌰𐌹𐍃, 𐌽𐌹𐌷 𐌰𐍄𐍃𐌽𐌰𐍂𐍀𐌾𐌰𐌹𐍃, 𐌽𐌹𐌷 𐌺𐌰𐌿𐍃𐌾𐌰𐌹𐍃! 𐌽𐌹 𐍄𐌴𐌹𐌺𐌰𐌹𐍃, 𐌽𐌹 𐌰𐍄𐍃𐌽𐌰𐍂𐍀𐌾𐌰𐌹𐍃, 𐌽𐌹 𐌺𐌰𐌿𐍃𐌾𐌰𐌹𐍃!',
        22: '𐌸𐌰𐍄𐌴𐌹 𐌹𐍃𐍄 𐌰𐌻𐌻 𐌳𐌿 𐍂𐌹𐌿𐍂𐌴𐌹𐌽, 𐌸𐌰𐌹𐍂𐌷 𐌸𐌰𐍄𐌴𐌹 𐌹𐍃 𐌱𐍂𐌿𐌺𐌾𐌰𐌹𐌳𐌰𐌿 𐌱𐌹 𐌰𐌽𐌰𐌱𐌿𐍃𐌽𐌹𐌼 𐌾𐌰𐌷 𐌻𐌰𐌹𐍃𐌴𐌹𐌽𐌹𐌼 𐌼𐌰𐌽𐌽𐌴, 𐌸𐌰𐍄𐌴𐌹 𐌹𐍃𐍄 𐌰𐌻𐌻 𐌳𐌿 𐍂𐌹𐌿𐍂𐌴𐌹𐌽, 𐌸𐌰𐌹𐍂𐌷 𐌸𐌰𐍄𐌴𐌹 𐌹𐍃 𐌱𐍂𐌿𐌺𐌾𐌰𐌹𐌳𐌰𐌿 𐌱(𐌹) 𐌰𐌽𐌰𐌱𐌿𐍃𐌽𐌹𐌼 𐌾𐌰𐌷 𐌻𐌰𐌹𐍃𐌴𐌹𐌽𐌹𐌼 𐌼𐌰𐌽𐌽𐌴,',
        23: '𐌸𐍉𐌴𐌹 𐍃𐌹𐌽𐌳 𐍃𐍅𐌴𐌸𐌰𐌿𐌷 𐍅𐌰𐌿𐍂𐌳 𐌷𐌰𐌱𐌰𐌽𐌳𐍉𐌽𐌰 𐌷𐌰𐌽𐌳𐌿𐌲𐌴𐌹𐌽𐍃 [𐌸𐌿𐌷𐍄𐌰𐌿𐍃] 𐌹𐌽 𐍆𐌰𐍃𐍄𐌿𐌱𐌽𐌾𐌰 𐌾𐌰𐌷 𐌷𐌰𐌿𐌽𐌴𐌹𐌽𐌰𐌹 𐌷𐌰𐌹𐍂𐍄𐌹𐌽𐍃 𐌾𐌰𐌷 𐌿𐌽𐍆𐍂𐌴𐌹𐌳𐌴𐌹𐌽𐌰𐌹 𐌻𐌴𐌹𐌺𐌹𐍃, 𐌽𐌹 𐌹𐌽 𐍃𐍅𐌴𐍂𐌹𐌸𐍉 𐍈𐌹𐌶𐌰𐌹 𐌳𐌿 𐍃𐍉𐌸𐌰 𐌻𐌴𐌹𐌺𐌹𐍃. 𐌸𐍉𐌴𐌹 𐍃𐌹𐌽𐌳 𐍃𐍅𐌴𐌸𐌰(𐌿𐌷) 𐍅𐌰𐌿𐍂𐌳 𐌷𐌰𐌱𐌰𐌽𐌳𐍉𐌽𐌰 𐌷𐌰𐌽𐌳𐌿𐌲(𐌴𐌹𐌽𐍃) [(𐌸)𐌿𐌷𐍄𐌰𐌿𐍃] 𐌹𐌽 𐍆𐌰𐍃𐍄𐌿𐌱𐌽𐌾𐌰 𐌾𐌰𐌷 𐌷𐌰𐌿𐌽𐌴𐌹𐌽𐌰𐌹 𐌷𐌰𐌹𐍂𐍄𐌹𐌽𐍃 𐌾𐌰𐌷 𐌿𐌽𐍆𐍂𐌴𐌹𐌳𐌴𐌹 𐌻𐌴𐌹𐌺𐌹𐍃, 𐌽𐌹 𐌹𐌽 𐍃𐍅𐌴𐍂𐌹𐌸𐍉 𐍈𐌹𐌶𐌰𐌹 𐌳𐌿 𐍃𐍉𐌸𐌰 𐌻𐌴𐌹𐌺𐌹𐍃.',
    },
    3: {
        1: '𐌾𐌰𐌱𐌰𐌹 𐌽𐌿 𐌼𐌹𐌸𐌿𐍂𐍂𐌹𐍃𐌿𐌸 𐍇𐍂𐌹𐍃𐍄𐌰𐌿, 𐌸𐍉𐌴𐌹 𐌹𐌿𐍀𐌰 𐍃𐌹𐌽𐌳 𐍃𐍉𐌺𐌴𐌹𐌸, 𐌸𐌰𐍂𐌴𐌹 𐍇𐍂𐌹𐍃𐍄𐌿𐍃 𐌹𐍃𐍄 𐌹𐌽 𐍄𐌰𐌹𐌷𐍃𐍅𐌰𐌹 𐌲𐌿𐌳𐌹𐍃 𐍃𐌹𐍄𐌰𐌽𐌳𐍃. 𐌾𐌰𐌱𐌰𐌹 𐌽𐌿 𐌼𐌹𐌸𐌿𐍂𐍂𐌹𐍃𐌿𐌸 𐍇𐍂𐌹𐍃𐍄𐌰𐌿, 𐌸𐍉𐌴𐌹 𐌹𐌿𐍀𐌰 𐍃𐌹𐌽𐌳 𐍃𐍉𐌺𐌴𐌹𐌸, 𐌸𐌰𐍂𐌴𐌹 𐍇𐍂𐌹𐍃𐍄𐌿𐍃 𐌹𐍃𐍄 𐌹𐌽 𐍄𐌰𐌹𐌷𐍃𐍅𐌰𐌹 𐌲𐌿𐌳𐌹𐍃 𐍃𐌹𐍄𐌰𐌽𐌳𐍃.',
        2: '𐌸𐌰𐌹𐌼𐌴𐌹 𐌹𐌿𐍀𐌰 𐍃𐌹𐌽𐌳 𐍆𐍂𐌰𐌸𐌾𐌰𐌹𐌸, 𐌽𐌹 𐌸𐌰𐌹𐌼 𐌸𐍉𐌴𐌹 𐌰𐌽𐌰 𐌰𐌹𐍂𐌸𐌰𐌹 𐍃𐌹𐌽𐌳. 𐌸𐌰𐌹𐌼𐌴𐌹 𐌹𐌿𐍀𐌰 𐍃𐌹𐌽𐌳 𐍆𐍂𐌰𐌸𐌾𐌰𐌹𐌸, 𐌽𐌹 𐌸𐌰𐌹𐌼 𐌸𐍉𐌴𐌹 𐌰𐌽𐌰 𐌰𐌹𐍂𐌸𐌰𐌹 𐍃𐌹𐌽𐌳.',
        3: '𐌿𐌽𐍄𐌴 𐌲𐌰𐌳𐌰𐌿𐌸𐌽𐍉𐌳𐌴𐌳𐌿𐌸 𐌾𐌰𐌷 𐌻𐌹𐌱𐌰𐌹𐌽𐍃 𐌹𐌶𐍅𐌰𐍂𐌰 𐌲𐌰𐍆𐌿𐌻𐌲𐌹𐌽𐌰 𐌹𐍃𐍄 𐌼𐌹𐌸 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌽 𐌲𐌿𐌳𐌰. 𐌿𐌽𐍄𐌴 𐌲𐌰𐌳𐌰𐌿𐌸𐌽𐍉𐌳𐌴𐌳𐌿𐌸 𐌾𐌰𐌷 𐌻𐌹𐌱𐌰𐌹𐌽𐍃 𐌹𐌶𐍅𐌰𐍂𐌰 𐌲𐌰𐍆𐌿𐌻𐌲𐌹𐌽𐌰 𐌹𐍃𐍄 𐌼𐌹𐌸 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌽 𐌲𐌿𐌳𐌰.',
        4: '𐌸𐌰𐌽 𐍇𐍂𐌹𐍃𐍄𐌿𐍃 𐍃𐍅𐌹𐌺𐌿𐌽𐌸𐍃 𐍅𐌰𐌹𐍂𐌸𐌹𐌸, 𐌻𐌹𐌱𐌰𐌹𐌽𐍃 𐌹𐌶𐍅𐌰𐍂𐌰, 𐌸𐌰𐌽𐌿𐌷 𐌾𐌰𐌷 𐌾𐌿𐍃 𐌱𐌰𐌹𐍂𐌷𐍄𐌰𐌹 𐍅𐌰𐌹𐍂𐌸𐌹𐌸 𐌼𐌹𐌸 𐌹𐌼𐌼𐌰 𐌹𐌽 𐍅𐌿𐌻𐌸𐌰𐌿. 𐌸𐌰𐌽 𐍇𐍂𐌹𐍃𐍄𐌿𐍃 𐍃𐍅𐌹𐌺𐌿𐌽𐌸𐍃 𐍅𐌰𐌹𐍂𐌸𐌹𐌸, 𐌻𐌹𐌱𐌰𐌹𐌽𐍃 𐌹𐌶𐍅𐌰𐍂𐌰, (𐌸𐌰𐌽)𐌿𐌷 𐌾𐌰𐌷 𐌾𐌿𐍃 𐌱𐌰𐌹𐍂𐌷𐍄𐌰𐌹 𐍅𐌰𐌹𐍂(𐌸𐌹𐌸) 𐌼𐌹𐌸 𐌹𐌼𐌼𐌰 𐌹𐌽 𐍅𐌿𐌻𐌸𐌰𐌿.',
        5: '𐌳𐌰𐌿𐌸𐌴𐌹𐌸 𐌽𐌿 𐌻𐌹𐌸𐌿𐌽𐍃 𐌹𐌶𐍅𐌰𐍂𐌰𐌽𐍃, 𐌸𐌰𐌽𐍃 𐌸𐌰𐌹𐌴𐌹 𐍃𐌹𐌽𐌳 𐌰𐌽𐌰 𐌰𐌹𐍂𐌸𐌰𐌹, 𐌷𐍉𐍂𐌹𐌽𐌰𐍃𐍃𐌰𐌿, 𐌿𐌽𐌷𐍂𐌰𐌹𐌽𐌴𐌹𐌽, 𐍅𐌹𐌽𐌽𐌰, 𐌻𐌿𐍃𐍄𐌰𐌿 𐌿𐌱𐌹𐌻𐌰𐌽𐌰 𐌾𐌰𐌷 𐍆𐌰𐌹𐌷𐌿𐌲𐌴𐌹𐍂𐍉𐌽, 𐍃(𐍉)𐌴𐌹 𐌹𐍃𐍄 𐌲𐌰𐌻𐌹𐌿𐌲𐌰𐌲𐌿𐌳𐌴 𐍃𐌺𐌰𐌻𐌺𐌹𐌽𐌰𐍃𐍃𐌿𐍃; 𐌳𐌰(𐌿𐌸)𐌴𐌹𐌸 𐌽𐌿 𐌻𐌹𐌸𐌿𐌽𐍃 𐌹𐌶𐍅𐌰𐍂𐌰𐌽𐍃, 𐌸𐌰𐌽𐍃 𐌸𐌰𐌹𐌴𐌹 𐍃𐌹𐌽𐌳 𐌰𐌽𐌰 𐌰𐌹𐍂𐌸𐌰𐌹, 𐌷𐍉𐍂𐌹𐌽𐌰𐍃𐍃𐌿, 𐌿𐌽𐌷𐍂𐌰𐌹𐌽𐌴𐌹𐌽, 𐍅𐌹𐌽𐌽𐍉𐌽, 𐌻𐌿𐍃𐍄𐌿 𐌿𐌱𐌹𐌻𐌰(𐌽𐌰) 𐌾𐌰𐌷 𐍆𐌰𐌹𐌷𐌿𐌲𐌴𐌹𐍂𐍉𐌽, 𐍃𐌴𐌹 𐌹𐍃𐍄 𐌲𐌰𐌻𐌹𐌿𐌲𐌰(𐌲𐌿)𐌳𐌴 𐍃𐌺𐌰𐌻𐌺𐌹𐌽𐌰𐍃𐍃𐌿𐍃;',
        6: '𐌸𐌰𐌹𐍂𐌷 𐌸𐍉𐌴𐌹 𐌵𐌹𐌼𐌹𐌸 𐌷𐌰𐍄𐌹𐍃 𐌲𐌿𐌳𐌹𐍃 𐌰𐌽𐌰 𐍃𐌿𐌽𐌿𐌼 𐌿𐌽𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹𐍃, 𐌸𐌰𐌹𐍂𐌷 𐌸𐍉𐌴𐌹 𐌵𐌹𐌼𐌹𐌸 𐌷𐌰𐍄𐌹𐍃 𐌲𐌿𐌳𐌹𐍃 𐌰𐌽𐌰 𐍃𐌿𐌽𐌿𐌼 𐌿𐌽𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹𐍃,',
        7: '𐌹𐌽 𐌸𐌰𐌹𐌼𐌴𐌹 𐌾𐌰𐌷 𐌾𐌿𐍃 𐌹𐌳𐌳𐌾𐌴𐌳𐌿𐌸 𐍃𐌹𐌼𐌻𐌴, 𐌸𐌰𐌽 𐌻𐌹𐌱𐌰𐌹𐌳𐌴𐌳𐌿𐌸 𐌹𐌽 𐌸𐌰𐌹𐌼. 𐌹𐌽 𐌸𐌰𐌹𐌼𐌴𐌹 𐌾𐌰𐌷 𐌾𐌿𐍃 𐌹𐌳𐌳𐌾𐌴𐌳𐌿𐌸 𐍃𐌹𐌼𐌻𐌴, 𐌸𐌰𐌽 𐌻𐌹𐌱𐌰𐌹𐌳𐌴𐌳𐌿𐌸 𐌹𐌽 𐌸𐌰𐌹𐌼.',
        8: '𐌹𐌸 𐌽𐌿 𐌰𐍆𐌻𐌰𐌲𐌾𐌹𐌸 𐌾𐌰𐌷 𐌾𐌿𐍃 𐌸𐍉 𐌰𐌻𐌻𐌰, 𐌷𐌰𐍄𐌹𐍃, 𐌸𐍅𐌰𐌹𐍂𐌷𐌴𐌹𐌽, 𐌿𐌽𐍃𐌴𐌻𐌴𐌹𐌽, 𐌰𐌽𐌰𐌵𐌹𐍃𐍃, 𐌰𐌲𐌻𐌰𐌹𐍄𐌹𐍅𐌰𐌿𐍂𐌳𐌴𐌹𐌽; 𐌿𐍃 𐌼𐌿𐌽𐌸𐌰 𐌹𐌶𐍅𐌰𐍂𐌰𐌼𐌼𐌰 𐌽𐌹 [𐌽𐌹].... 𐌹𐌸 𐌽𐌿 𐌰𐍆𐌻𐌰𐌲𐌾𐌹𐌸 𐌾𐌰𐌷 𐌾𐌿𐍃 𐌸𐍉 𐌰𐌻𐌻𐌰, 𐌷𐌰𐍄𐌹𐍃, 𐌸𐍅𐌰𐌹𐍂𐌷𐌴𐌹𐌽, 𐌿𐌽𐍃𐌴𐌻𐌴𐌹𐌽, 𐌰𐌽𐌰𐌵𐌹𐍃𐍃, 𐌰𐌲𐌻𐌰𐌹𐍄𐌹𐍅𐌰𐌿𐍂𐌳𐌴𐌹𐌽; 𐌿𐍃 𐌼𐌿𐌽𐌸𐌰 𐌹𐌶𐍅𐌰𐍂𐌰𐌼𐌼𐌰 𐌽𐌹 𐌿𐍃𐌲𐌰𐌲𐌲𐌰𐌹.',
        9: '𐌽𐌹 𐌻𐌹𐌿𐌲𐌰𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉, 𐌰𐍆𐍃𐌻𐌰𐌿𐍀𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌶𐍅𐌹𐍃 𐌸𐌰𐌽𐌰 𐍆𐌰𐌹𐍂𐌽𐌾𐌰𐌽 𐌼𐌰𐌽𐌽𐌰𐌽 𐌼𐌹𐌸 𐍄𐍉𐌾𐌰𐌼 𐌹𐍃,',
        10: '𐌾𐌰𐌷 𐌲𐌰𐌷𐌰𐌼𐍉𐌸 𐌽𐌹𐌿𐌾𐌰𐌼𐌼𐌰, 𐌸𐌰𐌼𐌼𐌰 𐌰𐌽𐌰𐌽𐌹𐍅𐌹𐌳𐌹𐌽 𐌳𐌿 𐌿𐍆𐌺𐌿𐌽𐌸𐌾𐌰 (𐌱𐌹) (𐍆𐍂)𐌹𐍃𐌰𐌷𐍄𐌰𐌹 𐌸𐌹𐍃, 𐍃𐌰𐌴𐌹 𐌲𐌰𐍃𐌺𐍉𐍀 𐌹𐌽𐌰;',
        11: '𐌸𐌰𐍂𐌴𐌹 𐌽𐌹𐍃𐍄 𐌺𐍂𐌴𐌺𐍃 𐌾𐌰𐌷 𐌾𐌿𐌳𐌰𐌹𐌿𐍃, 𐌱𐌹𐌼𐌰𐌹𐍄 𐌾𐌰𐌷 𐍆𐌰𐌿𐍂𐌰𐍆𐌹𐌻𐌻𐌹, 𐌱𐌰𐍂𐌱𐌰𐍂(𐌿𐍃) (𐌾𐌰𐌷) (𐍃)𐌺𐍅𐌸𐌿𐍃, 𐍃𐌺𐌰𐌻𐌺𐍃 𐌾𐌰𐌷 𐍆𐍂𐌴𐌹𐍃, 𐌰𐌺 𐌰𐌻𐌻𐌰 𐌾𐌰𐌷 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹𐌼 𐍇𐍂𐌹𐍃𐍄𐌿𐍃.',
        12: '𐌲𐌰𐌷𐌰𐌼𐍉𐌸 𐌹𐌶𐍅𐌹𐍃 𐌽𐌿 𐍃𐍅𐌴 𐌲𐌰𐍅𐌰𐌻𐌹(𐌳)𐌰𐌹 𐌲𐌿𐌳𐌹𐍃, 𐍅𐌴𐌹𐌷𐌰𐌽𐍃 𐌾𐌰𐌷 𐍅𐌰𐌻𐌹𐍃𐌰𐌽𐍃, 𐌱𐍂𐌿𐍃𐍄𐍃 𐌱𐌻𐌴𐌹𐌸𐌴𐌹𐌽, [𐌰𐍂𐌼𐌰(𐌷𐌰𐌹)𐍂𐍄𐌴𐌹𐌽], 𐍃𐌴𐌻𐌴(𐌹𐌽), 𐌷𐌰𐌿𐌽𐌴𐌹𐌽 𐌰(𐌷𐌹𐌽𐍃), 𐌵𐌰𐌹𐍂𐍂𐌴𐌹𐌽, 𐌿𐍃𐌱𐌴𐌹𐍃𐌽𐌴𐌹𐌽.',
        13: '𐌸𐌿𐌻𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌶(𐍅𐌹𐍃) 𐌼𐌹𐍃𐍃𐍉 𐌾𐌰𐌷 𐍆𐍂𐌰𐌲𐌹𐌱𐌰𐌽𐌳𐌰𐌽𐍃 𐍃(𐌹𐌻𐌱𐌰𐌽)𐍃, 𐌾𐌰𐌱𐌰𐌹 𐍈𐌰𐍃 𐍅𐌹𐌸𐍂𐌰 𐍈𐌰𐌽𐌰 𐌷𐌰𐌱𐌰𐌹 𐍆𐌰𐌹𐍂𐌹𐌽𐌰; 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐍇𐍂𐌹𐍃𐍄𐌿𐍃 𐍆𐍂𐌰𐌲𐌰𐍆 𐌹𐌶𐍅𐌹𐍃, 𐍃𐍅𐌰 𐌾𐌰𐌷 𐌾𐌿𐍃 𐍄𐌰𐌿𐌾𐌰𐌹𐌸.',
        14: '𐌰𐌸𐌸𐌰𐌽 𐌿𐍆𐌰𐍂 𐌰𐌻𐌻𐌰 𐍆𐍂𐌹𐌰𐌸𐍅𐌰, 𐍃𐌴𐌹 𐌹𐍃𐍄 𐌲𐌰𐌱𐌹𐌽𐌳𐌹 𐌰𐌹𐌽𐌰𐌼𐌿𐌽𐌳𐌹𐌸𐍉𐍃.',
        15: '𐌾𐌰𐌷 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹 𐌲𐌿𐌳𐌹𐍃 𐍃𐍅𐌹𐌲𐌽𐌾𐌰𐌹[𐌸] 𐌹(𐌽) 𐌷𐌰𐌹𐍂𐍄𐌰𐌼 𐌹𐌶𐍅𐌰𐍂𐌰𐌹𐌼, 𐌹𐌽 𐌸𐌰𐌼𐌼𐌴𐌹 𐌾𐌰𐌷 𐌻𐌰𐌸𐍉𐌳𐌰𐌹 𐍅𐌴𐍃𐌿𐌸 𐌹𐌽 𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌻𐌴𐌹𐌺𐌰, 𐌾𐌰𐌷 𐌰𐍅𐌹𐌻𐌹𐌿𐌳𐍉𐌽𐌳𐌰𐌽𐍃 𐍅𐌰𐌹𐍂𐌸𐌰𐌹𐌸.',
        16: '𐍅𐌰𐌿𐍂𐌳 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃 𐌱𐌰𐌿𐌰𐌹 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃 𐌲𐌰𐌱𐌹𐌲𐌰𐌱𐌰, 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹 𐌷𐌰𐌽𐌳𐌿𐌲𐌴𐌹𐌽 𐌾𐌰𐌷 𐍆𐍂𐍉𐌳𐌴𐌹𐌽 𐌰𐌷(𐌼𐌴𐌹)𐌽𐌰𐌹 𐌻𐌰𐌹𐍃𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌾𐌰𐌷 𐍄𐌰𐌻𐌶(𐌾𐌰)𐌽𐌳𐌰𐌽𐍃 𐌹𐌶𐍅𐌹𐍃 𐍃𐌹𐌻𐌱𐌰𐌽𐍃 𐍀𐍃𐌰𐌻𐌼𐍉𐌼, 𐌷𐌰𐌶𐌴𐌹𐌽𐌹𐌼, 𐍃𐌰𐌲𐌲𐍅𐌹𐌼 𐌰𐌷𐌼𐌴𐌹𐌽𐌰𐌹𐌼, 𐌹𐌽 (𐌰𐌽)𐍃𐍄𐌰𐌹 𐍃𐌹𐌲𐌲(𐍅)𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌽 𐌷𐌰𐌹𐍂(𐍄)𐌰𐌼 𐌹𐌶𐍅𐌰𐍂𐌰𐌹𐌼 𐍆(𐍂𐌰𐌿𐌾𐌹𐌽).',
        17: '𐌰𐌻𐌻 𐌸𐌹𐍃𐍈𐌰𐌷 𐌸𐌰𐍄𐌴𐌹 𐍄𐌰𐌿(𐌾𐌰𐌹)𐌸 𐌹𐌽 𐍅𐌰𐌿𐍂(𐌳𐌰) 𐌰𐌹𐌸𐌸𐌰𐌿 𐌹𐌽 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰, (𐌰)𐌻𐌻 𐌹𐌽 𐌽𐌰𐌼𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌹𐌴𐍃𐌿𐌹𐍃, 𐌰𐍅𐌹𐌻𐌹𐌿𐌳𐍉𐌽𐌳𐌰𐌽𐍃 𐌲𐌿𐌳𐌰 𐌰𐍄𐍄𐌹𐌽 𐌸𐌰𐌹𐍂𐌷 𐌹𐌽𐌰.',
        18: '𐌾𐌿𐍃 𐌵𐌹𐌽𐍉𐌽𐍃, 𐌿𐍆𐌷𐌰𐌿𐍃𐌾𐌰𐌹𐌸 𐍅𐌰𐌹𐍂𐌰𐌼 𐌹𐌶𐍅𐌰𐍂𐌰𐌹𐌼, 𐍃𐍅𐌴 𐌲𐌰𐌵𐌹𐌼𐌹𐌸 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽.',
        19: '𐍅𐌰𐌹𐍂𐍉𐍃, 𐍆𐍂𐌹𐌾𐍉𐌸 𐌵𐌴𐌽𐌹𐌽𐍃 𐌹𐌶𐍅𐌰𐍂𐍉𐍃 𐌾𐌰𐌷 𐌽𐌹 𐍃𐌹𐌾𐌰𐌹𐌸 𐌱𐌰𐌹𐍄𐍂𐌰𐌹 (𐍅)𐌹𐌸𐍂𐌰 𐌸𐍉𐍃.',
        20: '𐌱𐌰𐍂𐌽𐌰, 𐌿𐍆𐌷𐌰𐌿𐍃𐌾𐌰𐌹𐌸 𐍆𐌰𐌳𐍂𐌴𐌹𐌽𐌰𐌼 𐌱𐌹 𐌰𐌻𐌻; 𐌿𐌽𐍄𐌴 𐌸𐌰𐍄𐌰 𐍅𐌰𐌹𐌻𐌰 𐌲𐌰𐌻𐌴𐌹𐌺𐌰𐌹𐌸 𐌹𐍃𐍄 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽.',
        21: '𐌾𐌿𐍃 𐌰𐍄𐍄𐌰𐌽𐍃, 𐌽𐌹 𐌲𐍂𐌰𐌼𐌾𐌰𐌹𐌸 𐌱𐌰𐍂𐌽𐌰 𐌹𐌶𐍅𐌰𐍂𐌰 𐌳𐌿 𐌸𐍅𐌰𐌹𐍂𐌷𐌴𐌹𐌽, 𐌴𐌹 𐌽𐌹 𐍅𐌰𐌹𐍂𐌸𐌰𐌹𐌽𐌰 𐌹𐌽 𐌿𐌽𐌻𐌿𐍃𐍄𐌰𐌿.',
        22: '𐌸𐌴𐍅𐌹𐍃𐌰, 𐌿𐍆𐌷𐌰𐌿𐍃𐌾𐌰𐌹𐌸 𐌱𐌹 𐌰𐌻𐌻 𐌻𐌴𐌹𐌺𐌰 𐍆𐍂𐌰𐌿𐌾𐌰𐌼, 𐌽𐌹 𐌹𐌽 𐌰𐌿𐌲𐌰𐌼 𐍃𐌺𐌰𐌻𐌺𐌹𐌽𐍉𐌽𐌳𐌰𐌽𐍃, 𐍃𐍅𐌴 𐌼𐌰𐌽𐌽𐌰𐌼 𐍃𐌰𐌼𐌾𐌰𐌽𐌳𐌰𐌽𐍃, 𐌰𐌺 𐌹𐌽 𐌰𐌹𐌽𐍆𐌰𐌻𐌸𐌴𐌹𐌽 𐌷𐌰𐌹𐍂𐍄𐌹𐌽𐍃, 𐍉𐌲𐌰𐌽𐌳𐌰𐌽𐍃 𐌲𐌿𐌸.',
        23: '𐌸𐌹𐍃𐍈𐌰𐌷 𐌸𐌰𐍄𐌴𐌹 𐍄𐌰𐌿𐌾𐌰𐌹𐌸, 𐌿𐍃 𐍃𐌰𐌹𐍅𐌰𐌻𐌰𐌹 𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌹𐌸 𐍃𐍅𐌴 𐍆𐍂𐌰𐌿𐌾𐌹𐌽, 𐌽𐌹 𐌼𐌰𐌽𐌽𐌰𐌼,',
        24: '𐍅𐌹𐍄𐌰𐌽𐌳𐌰𐌽𐍃 𐌸𐌰𐍄𐌴𐌹 𐌰𐍆 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐌽𐌹𐌼𐌹𐌸 𐌰𐌽𐌳𐌰𐌻𐌰𐌿𐌽𐌹 𐌰𐍂𐌱𐌾𐌹𐍃; 𐌿𐌽𐍄𐌴 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐍃𐌺𐌰𐌻𐌺𐌹𐌽𐍉𐌸.',
        25: '𐍃𐌰 𐌰𐌿𐌺 𐍃𐌺𐌰𐌸𐌰𐌹𐌻𐌰 𐌰𐌽𐌳𐌽𐌹𐌼𐌹𐌸 𐌸𐌰𐍄𐌴𐌹 𐍃𐌺𐍉𐌸, 𐌾𐌰𐌷 𐌽𐌹𐍃𐍄 𐍅𐌹𐌻𐌾𐌰𐌷𐌰𐌻𐌸𐌴𐌹𐌽 𐌰𐍄 𐌲𐌿𐌳𐌰.',
    },
    4: {
        1: '𐌾𐌿𐍃 𐍆𐍂𐌰𐌿𐌾𐌰𐌽𐍃, 𐌲𐌰𐍂𐌰𐌹𐌷𐍄 𐌾𐌰𐌷 𐌹𐌱𐌽𐌰𐍃𐍃𐌿 𐌸𐌴𐍅𐌹𐍃𐌰𐌼 𐌰𐍄𐌺𐌿𐌽𐌽𐌰𐌹𐌸, 𐍅𐌹𐍄𐌰𐌽𐌳𐌰𐌽𐍃 𐌸𐌰𐍄𐌴𐌹 𐌰𐌹𐌷𐌿𐌸 𐌾𐌰𐌷 𐌾𐌿𐍃 𐍆𐍂𐌰𐌿𐌾𐌰𐌽 𐌹𐌽 𐌷𐌹𐌼𐌹𐌽𐌰𐌼.',
        2: '𐌱𐌹𐌳𐌰𐌹 𐌷𐌰(𐍆)𐍄𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌶𐍅𐌹𐍃, 𐍅𐌰𐌺𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌽 𐌹𐌶𐌰𐌹 𐌹𐌽 𐌰𐍅𐌹𐌻𐌹𐌿𐌳𐌰𐌼;',
        3: '𐌱𐌹𐌳𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐍃𐌰𐌼𐌰𐌽𐌰 𐌾𐌰𐌷 𐌱𐌹 𐌿𐌽𐍃 𐌴𐌹 𐌲𐌿𐌸 𐌿𐍃𐌻𐌿𐌺𐌰𐌹 𐌿𐌽𐍃𐌹𐍃 𐌷𐌰𐌿𐍂𐌳 𐍅𐌰𐌿𐍂𐌳𐌹𐍃 𐌳𐌿 𐍂𐍉𐌳𐌾𐌰𐌽 𐍂𐌿𐌽𐌰 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃, 𐌹𐌽 𐌸𐌹𐌶𐍉𐌶𐌴𐌹 𐌾𐌰𐌷 𐌲𐌰𐌱𐌿𐌽𐌳𐌰𐌽𐍃 𐌹𐌼,',
        4: '.... 𐌸𐍉, 𐍃𐍅𐌰𐍃𐍅𐌴 𐍃𐌺𐌿𐌻𐌾𐌰𐌿 𐍂𐍉𐌳𐌾𐌰𐌽. 𐌴𐌹 𐌲𐌰𐌱𐌰𐌹𐍂𐌷𐍄𐌾𐌰𐌿 𐌸𐍉, 𐍃𐍅𐌰𐍃𐍅𐌴 𐍃𐌺𐌿𐌻𐌾𐌰𐌿 𐍂𐍉𐌳𐌾𐌰𐌽.',
        5: '𐌹𐌽 𐌷𐌰𐌽𐌳𐌿𐌲𐌴𐌹𐌽 𐌲𐌰𐌲𐌲𐌰𐌹𐌸 𐌳𐌿 𐌸𐌰𐌹𐌼 𐌿𐍄𐌰, 𐌼𐌴𐌻 𐌿𐍃𐌱𐌿𐌲𐌾𐌰𐌽𐌳𐌰𐌽𐍃. 𐌹𐌽 𐌷𐌰𐌽𐌳𐌿𐌲𐌴𐌹𐌽 𐌲𐌰𐌲𐌲𐌰𐌹𐌸 𐌳𐌿 𐌸𐌰𐌹𐌼 𐌿𐍄𐌰, 𐌸𐌰𐍄𐌰 𐌼𐌴𐌻 𐌿𐍃𐌱𐌿𐌲𐌾𐌰𐌽𐌳𐌰𐌽𐍃.',
        6: '𐍅𐌰𐌿𐍂𐌳 𐌹𐌶𐍅𐌰𐍂 𐍃𐌹𐌽𐍄𐌴𐌹𐌽𐍉 𐌹𐌽 𐌰𐌽𐍃𐍄𐌰𐌹 𐍃𐌰𐌻𐍄𐌰 𐌲𐌰𐍃𐌿𐍀𐍉𐌸 𐍃𐌹𐌾𐌰𐌹, 𐌴𐌹 𐍅𐌹𐍄𐌴𐌹𐌸 𐍈𐌰𐌹𐍅𐌰 𐍃𐌺𐌿𐌻𐌴𐌹𐌸 𐌰𐌹𐌽𐍈𐌰𐍂𐌾𐌰𐌼𐌼𐌴𐌷 𐌰𐌽𐌳𐌷𐌰𐍆𐌾𐌰𐌽. 𐍅𐌰𐌿𐍂𐌳 𐌹𐌶𐍅𐌰𐍂 𐍃𐌹𐌽𐍄𐌴𐌹𐌽𐍉 𐌹𐌽 𐌰𐌽𐍃𐍄𐌰𐌹 𐍃𐌰𐌻𐍄𐌰 𐌲𐌰𐍃𐌿𐍀𐍉𐌸 𐍃𐌹𐌰𐌹, 𐌴𐌹 𐍅𐌹𐍄𐌴𐌹𐌸 𐍈𐌰𐌹𐍅𐌰 𐍃𐌺𐌿𐌻𐌴𐌹𐌸 𐌰𐌹𐌽𐍈𐌰𐍂𐌾𐌰𐌼𐌼𐌴𐌷 𐌰𐌽𐌳𐌷𐌰𐍆𐌾𐌰𐌽.',
        7: '𐌸𐌰𐍄𐌴𐌹 𐌱𐌹 𐌼𐌹𐌺 𐌹𐍃𐍄, 𐌰𐌻𐌻 𐌲𐌰𐌺𐌰𐌽𐌽𐌴𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐍄𐍅𐌺𐌴𐌹𐌺𐌿𐍃, 𐍃𐌰 𐌻𐌹𐌿𐌱𐌰 𐌱𐍂𐍉𐌸𐌰𐍂 𐌾𐌰𐌷 𐍄𐍂𐌹𐌲𐌲𐍅𐌰 𐌰𐌽𐌳𐌱𐌰𐌷𐍄𐍃 𐌾𐌰𐌷 𐌲𐌰𐍃𐌺𐌰𐌻𐌺𐌹 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽, 𐌸𐌰𐍄𐌴𐌹 𐌱𐌹 𐌼𐌹𐌺 𐌹𐍃𐍄, 𐌰𐌻𐌻 𐌲𐌰𐌺𐌰𐌽𐌽𐌴𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐍄𐍅𐌺𐌴𐌺𐌿𐍃, 𐍃𐌰 𐌻𐌹𐌿𐌱𐌰 𐌱𐍂𐍉𐌸𐌰𐍂 𐌾𐌰𐌷 𐍄𐍂𐌹𐌲𐌲𐍅𐌰 𐌰𐌽𐌳𐌱𐌰𐌷𐍄𐍃 𐌾𐌰𐌷 𐌲𐌰𐍃𐌺𐌰𐌻𐌺𐌹 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽,',
        8: '𐌸𐌰𐌽𐌴𐌹 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌰 𐌳𐌿 𐌹𐌶𐍅𐌹𐍃 𐌳𐌿𐌸𐌴 𐌴𐌹 𐌺𐌿𐌽𐌽𐌾𐌰(𐌹) 𐍈𐌰 𐌱𐌹 𐌹𐌶𐍅𐌹𐍃 𐌹𐍃𐍄, 𐌾𐌰𐌷 𐌲𐌰𐌸𐍂𐌰𐍆𐍃𐍄𐌾𐌰𐌹 𐌷𐌰𐌹𐍂𐍄𐍉𐌽𐌰 𐌹𐌶𐍅𐌰𐍂𐌰, 𐌸𐌰𐌽𐌴𐌹 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌰 𐌳𐌿 𐌹𐌶𐍅𐌹𐍃 𐌳𐌿𐌸𐌸𐌴 𐌴𐌹 𐌺𐌿𐌽𐌽𐌾𐌰𐌹 𐍈𐌰 𐌱𐌹 𐌹𐌶𐍅𐌹𐍃 𐌹𐍃𐍄, 𐌾𐌰𐌷 𐌲𐌰𐌸𐍂𐌰𐍆𐍃𐍄𐌾𐌰𐌹 𐌷𐌰𐌹𐍂𐍄𐍉𐌽𐌰 𐌹𐌶𐍅𐌰𐍂𐌰,',
        9: '𐌼𐌹𐌸 𐌰𐌿𐌽𐌹𐍃𐌹𐌼𐌰𐌿 𐌸𐌰𐌼𐌼𐌰 𐌻𐌹𐌿𐌱𐌹𐌽 𐌾𐌰𐌷 𐍄𐍂𐌹𐌲𐌲𐍅𐌹𐌽 𐌱𐍂𐍉𐌸𐍂, 𐍃𐌰𐌴𐌹 𐌹𐍃𐍄 𐌿𐍃 𐌹𐌶𐍅𐌹𐍃, 𐌸𐌰𐌹𐌴𐌹 𐌰𐌻𐌻 𐌹𐌶𐍅𐌹𐍃 𐌲𐌰𐌺𐌰𐌽𐌽𐌾𐌰𐌽𐌳 𐌸𐌰𐍄𐌴𐌹 𐌷𐌴𐍂 𐌹𐍃𐍄. 𐌼𐌹𐌸 𐌰𐌿𐌽𐌹𐍃𐌹𐌼𐌰𐌿 𐌸𐌰𐌼𐌼𐌰 𐌻𐌹𐌿𐌱𐌹𐌽 𐌾𐌰𐌷 𐍄𐍂𐌹𐌲𐌲𐍅𐌹𐌽 𐌱𐍂𐍉𐌸𐍂, 𐍃𐌰𐌴𐌹 𐌹𐍃𐍄 𐌿𐍃 𐌹𐌶𐍅𐌹𐍃, 𐌸𐌰𐌹𐌴𐌹 𐌰𐌻𐌻 𐌹𐌶𐍅𐌹𐍃 𐌲𐌰𐌺𐌰𐌽𐌽𐌾𐌰𐌽𐌳 𐌸𐌰𐍄𐌴𐌹 𐌷𐌴𐍂 𐌹𐍃𐍄.',
        10: '𐌲𐍉𐌻𐌴𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌰𐍂𐌹[𐌰]𐍃𐍄𐌰𐍂𐌺𐌿𐍃, 𐍃𐌰 𐌼𐌹𐌸𐍆𐍂𐌰𐌷𐌿𐌽𐌸𐌰𐌽𐌰 𐌼𐌹𐍃, 𐌾𐌰𐌷 𐌼𐌰𐍂𐌺𐌿𐍃 𐌲𐌰𐌳𐌹𐌻𐌹𐌲𐌲𐍃 𐌱𐌰𐍂𐌽𐌰𐌱𐌹𐌽𐍃, 𐌱𐌹 𐌸𐌰𐌽𐌴𐌹 𐌽𐌴𐌼𐌿𐌸 𐌰𐌽𐌰𐌱𐌿𐍃𐌽𐌹𐌽𐍃, 𐌴𐌹 𐌾𐌰𐌱𐌰𐌹 𐌵𐌹𐌼𐌰𐌹 𐌰𐍄 𐌹𐌶𐍅𐌹𐍃, 𐌰𐌽𐌳𐌽𐌹𐌼𐌰𐌹𐌸 𐌹𐌽𐌰; 𐌲𐍉𐌻𐌴𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌰𐍂𐌴𐌹𐍃𐍄𐌰𐍂𐌺𐌿𐍃, 𐍃𐌰 𐌼𐌹𐌸𐍆𐍂𐌰𐌷𐌿𐌽𐌸𐌰𐌽𐌰 𐌼𐌹𐍃, 𐌾𐌰𐌷 𐌼𐌰𐍂𐌺𐌿𐍃 𐌲𐌰𐌳𐌹𐌻𐌹𐌲𐌲𐍃 𐌱𐌰𐍂𐌽𐌰𐌱𐌹𐌽𐍃, 𐌱𐌹 𐌸𐌰𐌽𐌴𐌹 𐌽𐌴𐌼𐌿𐌸 𐌰𐌽𐌰𐌱𐌿𐍃𐌽𐌹𐌽𐍃, 𐌴𐌹 𐌾𐌰𐌱𐌰𐌹 𐌵𐌹𐌼𐌰𐌹 𐌰𐍄 𐌹𐌶𐍅𐌹𐍃, 𐌰𐌽𐌳𐌽𐌹𐌼𐌰𐌹𐌸 𐌹𐌽𐌰;',
        11: '𐌾𐌰𐌷 𐌹𐌴𐍃𐌿𐍃, 𐍃𐌰𐌴𐌹 𐌷𐌰𐌹𐍄𐌰𐌳𐌰 𐌾𐌿𐍃𐍄𐌿𐍃, 𐌸𐌰𐌹𐌴𐌹 𐍃𐌹𐌽𐌳 𐌿𐍃 𐌱𐌹𐌼𐌰𐌹𐍄𐌰. 𐌸𐌰𐌹 𐌰𐌹𐌽𐌰𐌹 𐌲𐌰𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰𐌽𐍃 𐍃𐌹𐌽𐌳 𐌸𐌹𐌿𐌳𐌰𐌽𐌲𐌰𐍂𐌳𐌾𐍉𐍃 𐌲𐌿𐌳𐌹𐍃, 𐌸𐌰𐌹𐌴𐌹 𐍅𐌴𐍃𐌿𐌽 𐌼𐌹𐍃 𐌳𐌿 𐌲𐌰𐌸𐍂𐌰𐍆𐍃𐍄𐌴𐌹𐌽𐌰𐌹. 𐌾𐌰𐌷 𐌹𐌴𐍃𐌿𐍃, 𐍃𐌰𐌴𐌹 𐌷𐌰𐌹𐍄𐌰𐌳𐌰 𐌾𐌿𐍃𐍄𐌿𐍃, 𐌸𐌰𐌹𐌴𐌹 𐍃𐌹𐌽𐌳 𐌿𐍃 𐌱𐌹𐌼𐌰𐌹𐍄𐌰. 𐌸𐌰𐌹 𐌰𐌹𐌽𐌰𐌹 𐌲𐌰𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰𐌽𐍃 𐍃𐌹𐌽𐌳 𐌸𐌹𐌿𐌳𐌰𐌽𐌲𐌰𐍂𐌳𐌾𐍉𐍃 𐌲𐌿𐌳𐌹𐍃, 𐌸𐌰𐌹𐌴𐌹 𐍅𐌴𐍃𐌿𐌽 𐌼𐌹𐍃 𐌳𐌿 𐌲𐌰𐌸𐍂𐌰𐍆𐍃𐍄𐌴𐌹𐌽𐌰𐌹.',
        12: '𐌲𐍉𐌻𐌴𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌰𐌹𐍀𐌰𐍆𐍂𐌰𐍃, 𐍃𐌰 𐌿𐍃 𐌹𐌶𐍅𐌹𐍃, 𐍃𐌺𐌰𐌻𐌺𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃, 𐍃𐌰 𐍃𐌹𐌽𐍄𐌴𐌹𐌽𐍉 𐌿𐍃𐌳𐌰𐌿𐌳𐌾𐌰𐌽𐌳𐍃 𐌱𐌹 𐌹𐌶𐍅𐌹𐍃 𐌹𐌽 𐌱𐌹𐌳𐍉𐌼, 𐌴𐌹 𐍃𐍄𐌰𐌽𐌳𐌰𐌹𐌸 𐌰𐌻𐌻𐌰𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰𐌽𐍃 𐌾𐌰𐌷 𐍆𐌿𐌻𐌻𐌰𐍅𐌹𐍄𐌰𐌽𐍃 𐌹𐌽 𐌰𐌻𐌻𐌰𐌼𐌼𐌰 𐍅𐌹𐌻𐌾𐌹𐌽 𐌲𐌿𐌳𐌹𐍃. 𐌲𐍉𐌻𐌴𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌰𐌹𐍀𐌰𐍆𐍂𐌰𐍃, 𐍃𐌰 𐌿𐍃 𐌹𐌶𐍅𐌹𐍃, 𐍃𐌺𐌰𐌻𐌺𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃 𐌹𐌴𐍃𐌿𐌹𐍃, 𐍃𐌹𐌽𐍄𐌴𐌹𐌽𐍉 𐌿𐍃𐌳𐌰𐌿𐌳𐌾𐌰𐌽𐌳𐍃 𐌱𐌹 𐌹𐌶𐍅𐌹𐍃 𐌹𐌽 𐌱𐌹𐌳𐍉𐌼, 𐌴𐌹 𐍃𐍄𐌰𐌽𐌳𐌰𐌹𐌸 𐌰𐌻𐌻𐌰𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰𐌽𐍃 𐌾𐌰𐌷 𐍆𐌿𐌻𐌻𐌰𐍅𐌹𐍄𐌰𐌽𐍃 𐌹𐌽 𐌰𐌻𐌻𐌰𐌼𐌼𐌰 𐍅𐌹𐌻𐌾𐌹𐌽 𐌲𐌿𐌳𐌹𐍃.',
        13: '𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌾𐌰 𐌰𐌿𐌺 𐌹𐌼𐌼𐌰 𐌸𐌰𐍄𐌴𐌹 𐌷𐌰𐌱𐌰𐌹𐌸 𐌼𐌰𐌽𐌰𐌲 𐌰𐌻𐌾𐌰𐌽 𐌱𐌹 𐌹𐌶𐍅𐌹𐍃 𐌾𐌰𐌷 𐌱𐌹 𐌸𐌰𐌽𐍃 𐌸𐌰𐌹𐌴𐌹 𐍃𐌹𐌽𐌳.... 𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌾𐌰 𐌰𐌿𐌺 𐌹𐌼𐌼𐌰 𐌸𐌰𐍄𐌴𐌹 𐌷𐌰𐌱𐌰𐌹𐌸 𐌼𐌰𐌽𐌰𐌲 𐌰𐌻𐌾𐌰𐌽 𐌱𐌹 𐌹𐌶𐍅𐌹𐍃 𐌾𐌰𐌷 𐌱𐌹 𐌸𐌰𐌽𐍃 𐌸𐌰𐌹𐌴𐌹 𐍃𐌹𐌽𐌳 𐌹𐌽 𐌻𐌰𐌿𐌳𐌴𐌹𐌺𐌰𐌹𐌰 𐌾𐌰𐌷 𐌹𐌰𐌹𐍂𐌰𐌿𐍀𐌰𐌿𐌻𐌴𐌹𐌽.',
        14: '𐌲𐍉𐌻𐌴𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌻𐌿𐌺𐌰𐍃, 𐌻𐌴𐌹𐌺𐌴𐌹𐍃 𐍃𐌰 𐌻𐌹𐌿𐌱𐌰.',
        15: '𐌲𐍉𐌻𐌴𐌹𐌸 𐌸𐌰𐌽𐍃 𐌹𐌽 𐌻𐌰𐌿𐌳𐌴𐌹𐌺𐌰𐌹𐌰 𐌱𐍂𐍉𐌸𐍂𐌿𐌽𐍃 𐌾𐌰𐌷 𐌽𐍅𐌼𐍆𐌰𐌽 𐌾𐌰𐌷 𐌸𐍉 𐌹𐌽𐌲𐌰𐍂𐌳𐌾𐍉𐌽 𐌹𐍃 𐌰𐌹𐌺𐌺𐌻𐌴𐍃𐌾𐍉𐌽.',
        16: '𐌾𐌰𐌷 𐌸𐌰𐌽 𐌿𐍃𐍃𐌹𐌲𐌲𐍅𐌰𐌹𐌳𐌰𐌿 𐌰𐍄 𐌹𐌶𐍅𐌹𐍃 𐍃𐍉 𐌰𐌹𐍀𐌹𐍃𐍄𐌰𐌿𐌻𐌴, 𐍄𐌰𐌿𐌾𐌰𐌹𐌸 𐌴𐌹 𐌾𐌰𐌷 𐌹𐌽 𐌻𐌰𐌿𐌳𐌴𐌺𐌰𐌹𐍉𐌽 𐌰𐌹𐌺𐌺𐌻𐌴𐍃𐌾𐍉𐌽 𐌿𐍃𐍃𐌹𐌲𐌲𐍅𐌰𐌹𐌳𐌰𐌿, 𐌾𐌰𐌷 𐌸𐍉𐌴𐌹 𐌹𐍃𐍄 𐌿𐍃 𐌻𐌰𐌿𐌳𐌴𐌹𐌺𐌰𐌹𐍉𐌽, 𐌾𐌿𐍃 𐌿𐍃𐍃𐌹𐌲𐌲𐍅𐌰𐌹𐌳.',
        17: '𐌾𐌰𐌷 𐌵𐌹𐌸𐌰𐌹𐌸 𐌰𐍂𐌺𐌹𐍀𐍀𐌰𐌿: 𐍃𐌰𐌹𐍈 𐌸𐌰𐍄𐌰 𐌰𐌽𐌳𐌱𐌰𐌷𐍄𐌹 𐌸𐌰𐍄𐌴𐌹 𐌰𐌽𐌳𐌽𐌰𐌼𐍄 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽, 𐌴𐌹 𐌹𐍄𐌰 𐌿𐍃𐍆𐌿𐌻𐌻𐌾𐌰𐌹𐍃.',
        18: '𐌲𐍉𐌻𐌴𐌹𐌽𐍃 𐌼𐌴𐌹𐌽𐌰𐌹 𐌷𐌰𐌽𐌳𐌰𐌿 𐍀𐌰𐍅𐌻𐌰𐌿𐍃. [(Colossians 4:19) 𐌲𐌰𐌼𐌿𐌽𐌴𐌹𐌸 𐌼𐌴𐌹𐌽𐌰𐌹𐌶𐍉𐍃 𐌱𐌰𐌽𐌳𐌾𐍉𐍃. 𐌰𐌽𐍃𐍄𐍃 𐌼𐌹𐌸 𐌹𐌶𐍅𐌹𐍃, 𐌰𐌼𐌴𐌽.] [(Colossians 4:20) 𐌳𐌿 𐌺𐌰𐌿𐌻𐌰𐌿𐍃𐍃𐌰𐌹𐌿𐌼 𐌿𐍃𐍄𐌰𐌿𐌷.]',
    },
}
